import{_ as d,o as a,c as e,a5 as r}from"./chunks/framework.C1a7WKBV.js";const _=JSON.parse('{"title":"AI 术语速查表","description":"一页看懂 AI 时代的高频术语，按\\"模型 / 使用 / 进阶\\"分组。","frontmatter":{"title":"AI 术语速查表","description":"一页看懂 AI 时代的高频术语，按\\"模型 / 使用 / 进阶\\"分组。"},"headers":[],"relativePath":"concepts/glossary.md","filePath":"concepts/glossary.md","lastUpdated":1788838685000}'),o={name:"concepts/glossary.md"};function n(i,t,l,h,s,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-术语速查表" tabindex="-1">AI 术语速查表 <a class="header-anchor" href="#ai-术语速查表" aria-label="Permalink to &quot;AI 术语速查表&quot;">​</a></h1><p>读文档、看更新日志时最常见的术语，按使用场景分成三组。每条尽量一句话说清，配合前面的文章深入理解。</p><h2 id="_1-模型层-模型是什么、怎么来的" tabindex="-1">1. 模型层：模型是什么、怎么来的 <a class="header-anchor" href="#_1-模型层-模型是什么、怎么来的" aria-label="Permalink to &quot;1. 模型层：模型是什么、怎么来的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th></tr></thead><tbody><tr><td>LLM（大语言模型）</td><td>通过预测下一个词训练出来的通用文本模型，如 GPT、Claude、Gemini 系列</td></tr><tr><td>多模态（Multimodal）</td><td>能同时理解文字以外的图像、音频、视频的模型</td></tr><tr><td>推理模型（Reasoning Model）</td><td>回答前先&quot;内部思考&quot;一段再输出的模型，擅长数学、代码、复杂决策，如 o 系列</td></tr><tr><td>Token（词元）</td><td>模型处理文本的最小单位，计费和上下文长度都按它算</td></tr><tr><td>参数（Parameter）</td><td>模型内部的&quot;旋钮&quot;数量，通常越多能力越强、成本越高</td></tr><tr><td>上下文窗口（Context Window）</td><td>模型一次能&quot;看见&quot;的最大 token 数，超出就记不住</td></tr><tr><td>训练（Training）</td><td>用海量数据调整模型参数的过程，由 AI 公司完成</td></tr><tr><td>微调（Fine-tuning）</td><td>在已有模型上用特定数据继续训练，让它更适配某个领域</td></tr><tr><td>蒸馏（Distillation）</td><td>用大模型的输出训练小模型，让小模型便宜且够用</td></tr><tr><td>开源/开放权重（Open Weights）</td><td>模型参数可以下载本地部署，如 Llama、Qwen、DeepSeek</td></tr></tbody></table><h2 id="_2-使用层-日常对话和提示词" tabindex="-1">2. 使用层：日常对话和提示词 <a class="header-anchor" href="#_2-使用层-日常对话和提示词" aria-label="Permalink to &quot;2. 使用层：日常对话和提示词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th></tr></thead><tbody><tr><td>提示词（Prompt）</td><td>你发给 AI 的完整输入，质量直接决定回答质量</td></tr><tr><td>系统提示词（System Prompt）</td><td>应用在后台预置的隐藏指令，定义 AI 的角色和规矩</td></tr><tr><td>幻觉（Hallucination）</td><td>模型编造看似合理但不存在的内容，冷门事实务必验证</td></tr><tr><td>知识截止（Knowledge Cutoff）</td><td>模型知识的时间边界，之后的更新它不知道</td></tr><tr><td>Few-shot（少样本）</td><td>在提示词里给几个输入输出示例，让模型照着模仿</td></tr><tr><td>温度（Temperature）</td><td>控制输出随机性的参数，越低越稳定、越高越发散</td></tr><tr><td>流式输出（Streaming）</td><td>逐字实时显示回答，而不是等全部生成完再显示</td></tr></tbody></table><h2 id="_3-进阶层-agent-与应用架构" tabindex="-1">3. 进阶层：Agent 与应用架构 <a class="header-anchor" href="#_3-进阶层-agent-与应用架构" aria-label="Permalink to &quot;3. 进阶层：Agent 与应用架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th></tr></thead><tbody><tr><td>Agent（智能体）</td><td>能自主调用工具、多步执行任务的 AI 系统</td></tr><tr><td>工具调用（Tool Calling）</td><td>模型输出结构化指令，让外部程序替它执行操作</td></tr><tr><td>MCP（模型上下文协议）</td><td>连接 AI 应用与外部工具的开放标准，相当于工具的 USB 接口</td></tr><tr><td>RAG（检索增强生成）</td><td>先从资料库检索相关内容，再让模型基于检索结果回答，减少幻觉</td></tr><tr><td>嵌入（Embedding）</td><td>把文本变成一串数字向量，使&quot;语义相近&quot;可以用距离计算，是搜索和 RAG 的基础</td></tr><tr><td>Vibe Coding</td><td>以自然语言描述需求、由 AI 生成代码为主的编程方式</td></tr><tr><td>视觉语言模型（VLM）</td><td>能看懂截图、图表并回答问题的模型，编程工具常用它分析界面</td></tr></tbody></table><h2 id="_4-使用建议" tabindex="-1">4. 使用建议 <a class="header-anchor" href="#_4-使用建议" aria-label="Permalink to &quot;4. 使用建议&quot;">​</a></h2><ol><li>不必背表。用到时回来查，读三次自然就记住了。</li><li>遇到新名词，先判断它属于哪一层：模型能力、使用技巧，还是应用架构——层次对了，理解就不会偏。</li><li>术语会过时，原理不会。token、上下文窗口、工具调用这些底层概念的生命周期，远长于任何产品名。</li></ol>',10)])])}const b=d(o,[["render",n]]);export{_ as __pageData,b as default};
